                pl.slice(moe_shared_tmp_stack, [BATCH, HIDDEN], [0 * BATCH, 0]),
                pl.slice(moe_shared_signal_stack, [n_ranks, 1], [0 * COMM_SIGNAL_STRIDE_I32, 0]),
