                pl.slice(moe_shared_signal_stack, [n_ranks, 1], [1 * COMM_SIGNAL_STRIDE_I32, 0]),
                pl.slice(moe_routed_y_stack, [n_routes_per_rank, HIDDEN], [1 * n_routes_per_rank, 0]),
